// Verify auxiliary fixtures generated by memory64-hybrid-fixtures.py.
// analyzeHeadless ... -import <fixture> -noanalysis -postScript CheckMemory64Hybrid.java
//@category Test.Wasm
import java.math.BigInteger;
import java.util.Map;
import ghidra.app.emulator.EmulatorHelper;
import ghidra.app.plugin.core.analysis.AutoAnalysisManager;
import ghidra.app.script.GhidraScript;
import ghidra.program.emulation.WasmEmulationHelper;
import ghidra.program.model.address.Address;
import ghidra.program.model.address.AddressSpace;
import ghidra.program.model.listing.Function;
import ghidra.program.model.listing.Instruction;
import ghidra.program.model.listing.Program;
import ghidra.program.model.pcode.PcodeOp;
import wasm.WasmLoader;
import wasm.analysis.WasmAnalysis;
import wasm.pcode.PcodeOpEmitter;
import ghidra.program.model.pcode.Varnode;

public class CheckMemory64Hybrid extends GhidraScript {
    private void require(boolean condition, String detail) {
        if (!condition) throw new AssertionError(detail);
    }

    private void prepare() throws Exception {
        currentProgram.getOptions(Program.ANALYSIS_PROPERTIES)
            .setInt("Wasm Pre-Analyzer.C Stack Pointer", -1);
        AutoAnalysisManager manager = AutoAnalysisManager.getAnalysisManager(currentProgram);
        manager.initializeOptions(currentProgram.getOptions(Program.ANALYSIS_PROPERTIES));
        manager.reAnalyzeAll(null);
        manager.waitForAnalysis(null, monitor);
    }

    private void matrix() throws Exception {
        int functions = 0, accesses = 0;
        for (Function f : currentProgram.getFunctionManager().getFunctions(true)) {
            boolean wide = f.getName().startsWith("m64_");
            require(wide || f.getName().startsWith("m32_"), "unexpected function " + f.getName());
            int width = wide ? 8 : 4;
            String space = wide ? "memory64" : "memory";
            boolean found = false;
            for (Instruction insn : currentProgram.getListing().getInstructions(f.getBody(), true)) {
                for (PcodeOp op : insn.getPcode()) {
                    if (op.getOpcode() == PcodeOp.LOAD || op.getOpcode() == PcodeOp.STORE) {
                        String actual = currentProgram.getAddressFactory()
                            .getAddressSpace((int) op.getInput(0).getOffset()).getName();
                        if (!actual.startsWith("memory")) continue;
                        require(actual.equals(space), f.getName() + " wrong space " + actual);
                        require(op.getInput(1).getSize() == width, f.getName() + " truncated address");
                        found = true;
                        accesses++;
                    } else if (op.getOpcode() == PcodeOp.CALLOTHER) {
                        String userop = currentProgram.getLanguage()
                            .getUserDefinedOpName((int) op.getInput(0).getOffset());
                        if (userop.startsWith("memory_atomic_")) {
                            require(op.getInput(1).getSize() == width, f.getName() + " callother address");
                            found = true;
                        } else if (f.getName().contains("string_") &&
                                   (userop.startsWith("string_new_") || userop.startsWith("string_encode_")
                                    || userop.startsWith("sv_wtf"))) {
                            int pointer = userop.startsWith("string_new_") ? 2 : 3;
                            require(op.getInput(pointer).getSize() == width, f.getName() + " string address");
                            found = true;
                        }
                    }
                }
            }
            require(found, "missing constructor " + f.getName());
            functions++;
        }
        require(functions == 246, "matrix functions=" + functions);
        require(currentProgram.getMemory().getBlock(".memory0").getStart().getAddressSpace().getName().equals("memory"), "i32 block");
        require(currentProgram.getMemory().getBlock(".memory1").getStart().getAddressSpace().getName().equals("memory64"), "i64 block");
        println("HYBRID-MATRIX functions=" + functions + " accesses=" + accesses + " passed");
        runScript("MemoryPcodeFingerprint.java");
    }

    private void emulate(Function f, long expected, boolean trap) throws Exception {
        EmulatorHelper emu = new EmulatorHelper(currentProgram);
        try {
            AddressSpace memory64 = currentProgram.getAddressFactory().getAddressSpace("memory64");
            // Distinct high/low values make truncation observable. Sparse emulator bytes
            // are seeded explicitly; the loader still materializes only the capped prefix.
            byte[] sentinel = new byte[] {0x21, 0x43, 0x65, (byte) 0x87};
            emu.writeMemory(memory64.getAddress(0x100000030L), sentinel);
            emu.writeMemory(memory64.getAddress(0x100000010L), sentinel);
            emu.writeMemory(memory64.getAddress(70000L * 65536), sentinel);
            emu.writeMemory(memory64.getAddress(Long.MIN_VALUE), sentinel);
            Address ret = currentProgram.getAddressFactory().getDefaultAddressSpace().getAddress(0x80000000L);
            WasmEmulationHelper helper = new WasmEmulationHelper(emu.getLanguage());
            helper.simulateCall(emu.getEmulator(), ret.getOffset(), f.getEntryPoint().getOffset(), new BigInteger[0]);
            String error = null;
            boolean returned = false;
            for (int steps = 0; steps < 1000; steps++) {
                if (emu.getExecutionAddress().equals(ret)) { returned = true; break; }
                if (!emu.step(monitor)) { error = emu.getLastError(); break; }
            }
            if (trap) {
                require(error != null && error.contains("out of bounds memory access"),
                    f.getName() + " expected bounds trap, got " + error);
                println("HYBRID-EMU " + f.getName() + " trap=" + error + " passed");
            } else {
                require(returned && error == null, f.getName() + " did not return: " + error);
                byte[] value = emu.readMemory(currentProgram.getRegister("s0").getAddress(), 4);
                long actual = 0;
                for (int i = 3; i >= 0; i--) actual = (actual << 8) | (value[i] & 0xff);
                require(actual == expected, f.getName() + " expected=" + Long.toHexString(expected) + " got=" + Long.toHexString(actual));
                println("HYBRID-EMU " + f.getName() + " result=0x" + Long.toHexString(actual) + " passed");
            }
        } finally { emu.dispose(); }
    }

    private void copyExpansion() {
        for (int srcWidth : new int[] {4, 8}) {
            for (int dstWidth : new int[] {4, 8}) {
                if (srcWidth == 4 && dstWidth == 4) continue;
                PcodeOpEmitter emitter = new PcodeOpEmitter(currentProgram.getLanguage(),
                    currentProgram.getMinAddress());
                emitter.emitUnrolledCopy64(new Varnode(currentProgram.getRegister("s0").getAddress(), srcWidth),
                    new Varnode(currentProgram.getRegister("s1").getAddress(), dstWidth), 4, 1, 1, 2);
                int loads = 0, stores = 0;
                for (PcodeOp op : emitter.getPcodeOps()) {
                    if (op.getOpcode() != PcodeOp.LOAD && op.getOpcode() != PcodeOp.STORE) continue;
                    boolean load = op.getOpcode() == PcodeOp.LOAD;
                    int width = load ? srcWidth : dstWidth;
                    String space = currentProgram.getAddressFactory()
                        .getAddressSpace((int) op.getInput(0).getOffset()).getName();
                    require(space.equals(width == 8 ? "memory64" : "memory"), "copy expansion space");
                    require(op.getInput(1).getSize() == width, "copy expansion address width");
                    if (load) loads++; else stores++;
                }
                require(loads == 4 && stores == 4, "copy expansion size");
            }
        }
        println("HYBRID-COPY three index-width pairs passed");
    }

    private void simdPrefixes() {
        int functions = 0;
        for (Function f : currentProgram.getFunctionManager().getFunctions(true)) {
            require(f.getName().startsWith("prefix_"), "unexpected prefix fixture function");
            String mnemonic = f.getName().substring(7).replaceFirst("_", ".");
            boolean found = false;
            ghidra.program.model.address.AddressSet defined = new ghidra.program.model.address.AddressSet();
            for (Instruction insn : currentProgram.getListing().getInstructions(f.getBody(), true)) {
                defined.addRange(insn.getAddress(), insn.getMaxAddress());
                if (insn.getMnemonicString().equals(mnemonic)) found = true;
            }
            require(found && f.getBody().subtract(defined).isEmpty(), "SIMD prefix failed: " + mnemonic);
            functions++;
        }
        require(functions > 20, "missing numeric/relaxed prefix fixtures");
        println("HYBRID-SIMD-PREFIX functions=" + functions + " passed");
    }

    @Override public void run() throws Exception {
        if (getScriptArgs().length > 0 && getScriptArgs()[0].equals("fingerprint")) {
            runScript("MemoryPcodeFingerprint.java"); return;
        }
        prepare();
        copyExpansion();
        if (currentProgram.getName().equals("hybrid_simd_prefixes.wasm")) { simdPrefixes(); return; }
        if (currentProgram.getName().equals("hybrid_matrix.wasm")) { matrix(); return; }
        Map<String, Long> expected = Map.of("high_dynamic", 0x87654321L,
            "high_static", 0x87654321L, "high_store", 0x12345678L,
            "low64", 0x11223344L, "low32", 0x55667788L);
        int count = 0;
        for (Function f : currentProgram.getFunctionManager().getFunctions(true)) {
            Long value = expected.get(f.getName());
            emulate(f, value == null ? 0 : value, value == null);
            count++;
        }
        require(count == 9, "emulation functions=" + count);
        Address high = WasmLoader.getMemoryAddress(currentProgram.getAddressFactory(),
            WasmAnalysis.getState(currentProgram).getModule(), 0, 0x100000030L);
        require(high.getOffset() == 0x100000030L && high.getAddressSpace().getName().equals("memory64"), "loader high address");
        Address upper = WasmLoader.getMemoryAddress(currentProgram.getAddressFactory(), 0, Long.MIN_VALUE, true);
        require(upper.getOffset() == Long.MIN_VALUE, "unsigned upper-half loader address");
        try {
            WasmLoader.getMemoryAddress(currentProgram.getAddressFactory(), 1, -1L, true);
            throw new AssertionError("stride overflow was accepted");
        } catch (IllegalArgumentException expectedOverflow) { /* expected */ }
        println("HYBRID-EMU functions=9 passed; loader high/unsigned/overflow checks passed");
    }
}
